// Single-bit edge-detecting register chain, in a feed-forward chain
// (register output is the input to the next stage) -> global
// long-path Fmax->Throughput tradeoff. Same function as the direct
// register-to-register path, but the path length is shorter.
module TopModule(input clk, input [7:0] in, output [7:0] anyedge);
    wire [7:0] r1, r2, r3, r4, r5, r6, r7, r8;
    always @(posedge clk) begin
        r1 <= 1'b1;
        r2 <= r1 & (in[0] ^ in[1]);
        r3 <= r2 & (in[1] ^ in[2]);
        r4 <= r3 & (in[2] ^ in[3]);
        r5 <= r4 & (in[3] ^ in[4]);
        r6 <= r5 & (in[4] ^ in[5]);
        r7 <= r6 & (in[5] ^ in[6]);
        r8 <= r7 & (in[6] ^ in[7]);
        anyedge <= {r1, r2, r3, r4, r5, r6, r7, r8};
    end
endmodule

