// input bit. Implement per bit, the long path -> shorten the critical path.
module TopModule(input clk, input [7:0] in, output [7:0] anyedge);
  reg [7:0] reg1;
  reg [7:0] reg2;
  reg [7:0] reg3;
  reg [7:0] reg4;
  reg [7:0] reg5;
  reg [7:0] reg6;
  reg [7:0] reg7;
  reg [7:0] reg8;
  wire [7:0] edges;
  reg [7:0] nextreg1;
  reg [7:0] nextreg2;
  reg [7:0] nextreg3;
  reg [7:0] nextreg4;
  reg [7:0] nextreg5;
  reg [7:0] nextreg6;
  reg [7:0] nextreg7;
  reg [7:0] nextreg8;
  always @(posedge clk) begin
    nextreg1 <= reg1;
    nextreg2 <= reg2;
    nextreg3 <= reg3;
    nextreg4 <= reg4;
    nextreg5 <= reg5;
    nextreg6 <= reg6;
    nextreg7 <= reg7;
    nextreg8 <= reg8;
    reg1 <= in[0];
    reg2 <= in[1];
    reg3 <= in[2];
    reg4 <= in[3];
    reg5 <= in[4];
    reg6 <= in[5];
    reg7 <= in[6];
    reg8 <= in[7];
  end
  assign edges[0] = reg1 & ~nextreg1;
  assign edges[1] = reg2 & ~nextreg2;
  assign edges[2] = reg3 & ~nextreg3;
  assign edges[3] = reg4 & ~nextreg4;
  assign edges[4] = reg5 & ~nextreg5;
  assign edges[5] = reg6 & ~nextreg6;
  assign edges[6] = reg7 & ~nextreg7;
  assign edges[7] = reg8 & ~nextreg8;
  assign anyedge = edges;
endmodule

